<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\{Auth,Csrf,Flash,Http,View};use App\Services\{AuthService,SessionService};final class AuthController{public function home():void{if(Auth::check()){header('Location: '.APP_BASE_URL.'/dashboard');exit;}View::render('auth/login',['flash'=>Flash::pull()]);}public function requestOtp():void{Csrf::verify($_POST['_csrf']??null);$email=strtolower(Http::post('email'));$name=Http::post('name');$phone=Http::post('phone');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new \RuntimeException('Correo inválido.');$svc=new AuthService();$u=$svc->findUserByEmail($email);if(!$u){if(strlen($name)<3)throw new \RuntimeException('Ingresa tu nombre para registrarte.');$u=$svc->register($email,$name,$phone?:null);} $svc->sendOtp($email);header('Location: '.APP_BASE_URL.'/otp');exit;}public function otp():void{View::render('auth/otp',['email'=>$_SESSION['otp_email']??'','flash'=>Flash::pull()]);}public function verify():void{Csrf::verify($_POST['_csrf']??null);$email=strtolower(Http::post('email'));$code=preg_replace('/\\D/','',Http::post('code'));(new AuthService())->verify($email,$code);header('Location: '.APP_BASE_URL.'/dashboard');exit;}public function logout():void{Csrf::verify($_POST['_csrf']??null);(new SessionService())->revokeCurrent();Auth::logoutRuntime();header('Location: '.APP_BASE_URL.'/');exit;}}
